// simple_node.cc en OMNeT++
void SimpleNode::handleMessage(cMessage *msg) {
    if (msg->isSelfMessage()) {
        send(new cPacket("data"), "out");
        scheduleAt(simTime() + exponential(1.0), timerMsg);
    } else { delete msg; }
}
